using Servicio.RetazoMarket.Business.DTOs.Producto;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;public static class ProductoMarketplaceBusinessMapper {public static ProductoMarketplaceResponse ToResponse(ProductoDataModel m)=>new(){id_producto=m.id_producto,id_linea=m.id_linea,prod_nombre=m.prod_nombre,prod_descripcion=m.prod_descripcion,colores=m.colores.Clone(),precio_base=m.precio_base,es_personalizable=m.es_personalizable,tiene_descuentos=m.tiene_descuentos,stock_actual=m.stock_actual,disponibilidad=m.stock_actual>0?"DISPONIBLE":"AGOTADO",linea_nombre=m.Linea?.lin_nombre,imagenes=m.Imagenes.OrderByDescending(x=>x.es_principal=="S").ThenBy(x=>x.orden).Select(x=>new ImagenMarketplaceResponse{id_imagen=x.id_imagen,url=x.url,es_principal=x.es_principal,orden=x.orden}).ToList()};}
